<?php
require_once __DIR__ . '/../../config/config.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='delete'){db()->prepare('DELETE FROM vehicles WHERE id=?')->execute([(int)$_POST['id']]);}
 if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$status=$_POST['status']??'Disponible';if(!in_array($status,['Disponible','En mission','Maintenance'],true))$status='Disponible';if($name!==''){$data=[$name,trim($_POST['brand']??''),trim($_POST['registration']??''),trim($_POST['capacity']??''),trim($_POST['wheels']??''),$status,trim($_POST['description']??'')];if($id){$data[]=$id;db()->prepare('UPDATE vehicles SET name=?,brand=?,registration=?,capacity=?,wheels=?,status=?,description=? WHERE id=?')->execute($data);}else{db()->prepare('INSERT INTO vehicles(name,brand,registration,capacity,wheels,status,description) VALUES(?,?,?,?,?,?,?)')->execute($data);}}}
 header('Location: vehicles.php');exit;
}
$edit=null;if(isset($_GET['edit'])){$s=db()->prepare('SELECT * FROM vehicles WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$items=db()->query('SELECT * FROM vehicles ORDER BY id DESC')->fetchAll();include '_header.php'; ?>
<div class="admin-title"><span class="eyebrow">FLOTTE</span><h1>Gestion des véhicules</h1></div>
<form class="panel editor-form" method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>">
<label>Nom du véhicule<input name="name" required value="<?= e($edit['name']??'') ?>"></label><label>Marque<input name="brand" value="<?= e($edit['brand']??'') ?>"></label><label>Immatriculation<input name="registration" value="<?= e($edit['registration']??'') ?>"></label><label>Capacité<input name="capacity" value="<?= e($edit['capacity']??'') ?>"></label><label>Nombre de roues<input name="wheels" value="<?= e($edit['wheels']??'') ?>"></label><label>État<select name="status"><?php foreach(['Disponible','En mission','Maintenance'] as $st): ?><option <?= (($edit['status']??'Disponible')===$st)?'selected':'' ?>><?= e($st) ?></option><?php endforeach; ?></select></label><label>Description<textarea name="description" rows="3"><?= e($edit['description']??'') ?></textarea></label><button class="btn"><?= $edit?'Mettre à jour':'Ajouter le véhicule' ?></button><?php if($edit): ?><a href="vehicles.php">Annuler</a><?php endif; ?></form>
<div class="panel"><div class="table-wrap"><table><thead><tr><th>Véhicule</th><th>Marque</th><th>Immatriculation</th><th>État</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $it): ?><tr><td><?= e($it['name']) ?></td><td><?= e($it['brand']) ?></td><td><?= e($it['registration']) ?></td><td><?= e($it['status']) ?></td><td><a href="?edit=<?= $it['id'] ?>">Modifier</a><form class="inline" method="post" onsubmit="return confirm('Supprimer ce véhicule ?')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $it['id'] ?>"><button class="link-danger">Supprimer</button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php include '_footer.php'; ?>
